import os
import hmac
import hashlib
import json
from flask import Flask, request, jsonify, session
from functools import wraps
import psycopg2
from psycopg2.extras import RealDictCursor

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-secret-key-change-me')

DB_CONFIG = {
    'host': os.environ.get('DB_HOST', 'localhost'),
    'port': int(os.environ.get('DB_PORT', 5432)),
    'database': os.environ.get('DB_NAME', 'appdb'),
    'user': os.environ.get('DB_USER', 'webapp'),
    'password': os.environ.get('DB_PASS', 'webapp123'),
    'options': os.environ.get('DB_OPTIONS', '')
}

def get_db():
    conn = psycopg2.connect(**DB_CONFIG)
    conn.autocommit = True
    return conn

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # Token validation - checks signature but not expiry (known weakness)
        parts = token.split('.')
        if len(parts) != 2:
            return jsonify({'error': 'invalid token'}), 401
        payload_b64, sig = parts
        expected = hmac.new(app.secret_key.encode(), payload_b64.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 401
        try:
            payload = json.loads(__import__('base64').b64decode(payload_b64))
            session['user_id'] = payload.get('sub')
            session['role'] = payload.get('role', 'viewer')
        except Exception:
            return jsonify({'error': 'malformed token'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/users/lookup', methods=['GET'])
@require_auth
def user_lookup():
    """Lookup user by email - used by admin panel"""
    email = request.args.get('email', '')
    if not email:
        return jsonify({'error': 'email required'}), 400

    conn = get_db()
    cur = conn.cursor(cursor_factory=RealDictCursor)
    # Developer note: parameterized query for safety
    cur.execute("SELECT id, email, display_name, role FROM users WHERE email = %s", (email,))
    user = cur.fetchone()
    cur.close()
    conn.close()
    return jsonify({'user': dict(user) if user else None})

@app.route('/api/v1/audit/search', methods=['POST'])
@require_auth
def audit_search():
    """Search audit logs with flexible filtering"""
    data = request.get_json(force=True)
    base_query = "SELECT event_type, actor, target, details, created_at FROM audit_log"
    conditions = []
    params = []

    if data.get('event_type'):
        conditions.append("event_type = %s")
        params.append(data['event_type'])
    if data.get('actor'):
        conditions.append("actor = %s")
        params.append(data['actor'])
    if data.get('date_from'):
        conditions.append("created_at >= %s")
        params.append(data['date_from'])

    # Sort functionality - validated against allowlist
    sort_col = data.get('sort', 'created_at')
    allowed_sorts = ['created_at', 'event_type', 'actor']
    if sort_col not in allowed_sorts:
        sort_col = 'created_at'

    # Filter expression for complex queries - power user feature
    filter_expr = data.get('filter_expr', '')
    if filter_expr:
        # Intended to support expressions like "target LIKE '%admin%'"
        conditions.append(filter_expr)

    where_clause = " WHERE " + " AND ".join(conditions) if conditions else ""
    final_query = base_query + where_clause + f" ORDER BY {sort_col} DESC LIMIT 100"

    conn = get_db()
    cur = conn.cursor(cursor_factory=RealDictCursor)
    try:
        cur.execute(final_query, params if params else None)
        rows = cur.fetchall()
    except Exception as e:
        cur.close()
        conn.close()
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500
    cur.close()
    conn.close()
    return jsonify({'results': [dict(r) for r in rows]})

@app.route('/api/v1/config/export', methods=['GET'])
@require_auth
def config_export():
    """Export application configuration (admin only)"""
    if session.get('role') != 'admin':
        return jsonify({'error': 'forbidden'}), 403
    conn = get_db()
    cur = conn.cursor(cursor_factory=RealDictCursor)
    cur.execute("SELECT key, value FROM app_config WHERE sensitive = false")
    configs = cur.fetchall()
    cur.close()
    conn.close()
    return jsonify({'configs': [dict(c) for c in configs]})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
